import { useMemo } from 'react';
import { create } from 'zustand';
import { subscribeWithSelector } from 'zustand/middleware';
import type { HintLevel, HintResponse } from '@pie/protocol';
import { hasGeneralLlm, type GeneralLlmAccess } from '@pie/solver/deepseek-client';

/**
 * Ghost node representing a hint suggestion
 */
export interface GhostNode {
  id: string;
  goalId: string;
  position: { x: number; y: number };
  hint: HintResponse;
  isLoading: boolean;
}

/**
 * Hint state for a specific goal
 */
export interface GoalHintState {
  goalId: string;
  currentLevel: HintLevel;
  hints: HintResponse[]; // History of hints at each level
  ghostNode: GhostNode | null;
  isLoading: boolean;
  error: string | null;
}

/**
 * Hint store state
 */
export interface HintState {
  // Map of goalId -> hint state
  goalHints: Map<string, GoalHintState>;

  // Currently active ghost node (only one at a time for clarity)
  activeGhostNodeId: string | null;

  // API key for AI-powered hints (optional)
  apiKey: string | null;

  // Proxy holding the General LLM key server-side. Build-time only; a user's
  // own apiKey takes priority.
  generalLlmProxyUrl: string | null;

  // URL of the LoRA tactic prediction server (local or Runpod serverless; optional)
  loraServerUrl: string | null;

  // Bearer token for the LoRA server. Only sent when loraServerUrl is a Runpod
  // serverless host (api.runpod.ai); ignored for a local server.
  loraApiKey: string | null;
}

/**
 * Hint store actions
 */
export interface HintActions {
  // Request a hint for a goal
  requestHint: (goalId: string) => void;

  // Set loading state for a goal
  setLoading: (goalId: string, isLoading: boolean) => void;

  // Update hint for a goal (called when worker responds)
  updateHint: (goalId: string, hint: HintResponse) => void;

  // Set error for a goal
  setError: (goalId: string, error: string | null) => void;

  // Create/update ghost node for a goal
  setGhostNode: (goalId: string, ghostNode: GhostNode | null) => void;

  // Accept the ghost node (convert to real tactic)
  acceptGhostNode: (goalId: string) => void;

  // Dismiss the ghost node
  dismissGhostNode: (goalId: string) => void;

  // Get more detail (next hint level)
  requestMoreDetail: (goalId: string) => void;

  moveGhostNode: (nodeId: string, position: { x: number; y: number }) => void;

  // Set API key
  setApiKey: (key: string | null) => void;

  // Set LoRA server URL (local or Runpod serverless)
  setLoraServerUrl: (url: string | null) => void;

  // Set LoRA server Bearer token (for Runpod serverless)
  setLoraApiKey: (key: string | null) => void;

  // Clear all hints
  clearAllHints: () => void;

  // Clear hint for a specific goal
  clearHint: (goalId: string) => void;

  // Get hint state for a goal
  getGoalHintState: (goalId: string) => GoalHintState | undefined;
}

export type HintStore = HintState & HintActions;

// Persist API key and LoRA URL to localStorage
const STORAGE_KEY_API = 'pie-slang:deepseek-api-key';
const STORAGE_KEY_LORA = 'pie-slang:lora-server-url';
const STORAGE_KEY_LORA_API = 'pie-slang:lora-api-key';

function loadFromStorage(key: string): string | null {
  try { return localStorage.getItem(key); } catch { return null; }
}
function saveToStorage(key: string, value: string | null) {
  try {
    if (value) localStorage.setItem(key, value);
    else localStorage.removeItem(key);
  } catch { /* ignore */ }
}

// The LoRA endpoint + Bearer token are NEVER hardcoded in the frontend. They
// come from build-time env vars (VITE_LORA_SERVER_URL / VITE_LORA_API_KEY),
// which a developer sets in web-react/.env.local (gitignored — see .env.example).
// A developer who leaves them unset just gets no LoRA hints (DeepSeek fallback
// still works); nothing is baked into the shipped bundle by default.
// Priority: localStorage (runtime override) > build-time env > null.
const env = (typeof import.meta !== 'undefined' && import.meta.env) || ({} as Record<string, string | undefined>);
const envApiKey = env.VITE_DEEPSEEK_API_KEY || null;
const envGeneralLlmProxyUrl = env.VITE_GENERAL_LLM_PROXY_URL || null;
const envLoraUrl = env.VITE_LORA_SERVER_URL || null;
const envLoraApiKey = env.VITE_LORA_API_KEY || null;

const initialState: HintState = {
  goalHints: new Map(),
  activeGhostNodeId: null,
  apiKey: loadFromStorage(STORAGE_KEY_API) || envApiKey,
  generalLlmProxyUrl: envGeneralLlmProxyUrl,
  loraServerUrl: loadFromStorage(STORAGE_KEY_LORA) || envLoraUrl,
  loraApiKey: loadFromStorage(STORAGE_KEY_LORA_API) || envLoraApiKey,
};

/**
 * Hint Store
 *
 * Manages the progressive hint system state including ghost nodes.
 */
export const useHintStore = create<HintStore>()(
  subscribeWithSelector((set, get) => ({
    ...initialState,

    requestHint: (goalId: string) => {
      set((state) => {
        const newGoalHints = new Map(state.goalHints);
        const existing = newGoalHints.get(goalId);

        if (existing) {
          // Already have hints - don't reset, just mark as loading
          newGoalHints.set(goalId, {
            ...existing,
            isLoading: true,
            error: null,
          });
        } else {
          // New hint request - start at category level
          newGoalHints.set(goalId, {
            goalId,
            currentLevel: 'category',
            hints: [],
            ghostNode: null,
            isLoading: true,
            error: null,
          });
        }

        return { goalHints: newGoalHints };
      });
    },

    setLoading: (goalId: string, isLoading: boolean) => {
      set((state) => {
        const newGoalHints = new Map(state.goalHints);
        const existing = newGoalHints.get(goalId);

        if (existing) {
          newGoalHints.set(goalId, { ...existing, isLoading });
        }

        return { goalHints: newGoalHints };
      });
    },

    updateHint: (goalId: string, hint: HintResponse) => {
      set((state) => {
        const newGoalHints = new Map(state.goalHints);
        const existing = newGoalHints.get(goalId);

        if (existing) {
          newGoalHints.set(goalId, {
            ...existing,
            currentLevel: hint.level,
            hints: [...existing.hints, hint],
            isLoading: false,
            error: null,
          });
        } else {
          newGoalHints.set(goalId, {
            goalId,
            currentLevel: hint.level,
            hints: [hint],
            ghostNode: null,
            isLoading: false,
            error: null,
          });
        }

        return { goalHints: newGoalHints };
      });
    },

    setError: (goalId: string, error: string | null) => {
      set((state) => {
        const newGoalHints = new Map(state.goalHints);
        const existing = newGoalHints.get(goalId);

        if (existing) {
          newGoalHints.set(goalId, {
            ...existing,
            isLoading: false,
            error,
          });
        }

        return { goalHints: newGoalHints };
      });
    },

    setGhostNode: (goalId: string, ghostNode: GhostNode | null) => {
      set((state) => {
        const newGoalHints = new Map(state.goalHints);
        const existing = newGoalHints.get(goalId);

        if (existing) {
          newGoalHints.set(goalId, { ...existing, ghostNode });
        }

        return {
          goalHints: newGoalHints,
          activeGhostNodeId: ghostNode?.id || null,
        };
      });
    },

    moveGhostNode: (nodeId, position) => {
      if (!Number.isFinite(position.x) || !Number.isFinite(position.y)) return;
      set((state) => {
        const match = [...state.goalHints].find(([, hint]) => hint.ghostNode?.id === nodeId);
        if (!match) return state;
        const [goalId, hint] = match;
        const goalHints = new Map(state.goalHints);
        goalHints.set(goalId, { ...hint, ghostNode: { ...hint.ghostNode!, position: { ...position } } });
        return { goalHints };
      });
    },

    acceptGhostNode: (goalId: string) => {
      // This will be handled by the UI component to create a real tactic node
      // Just clear the ghost node here
      get().dismissGhostNode(goalId);
    },

    dismissGhostNode: (goalId: string) => {
      set((state) => {
        const newGoalHints = new Map(state.goalHints);
        const existing = newGoalHints.get(goalId);

        if (existing) {
          newGoalHints.set(goalId, { ...existing, ghostNode: null });
        }

        return {
          goalHints: newGoalHints,
          activeGhostNodeId: state.activeGhostNodeId === existing?.ghostNode?.id
            ? null
            : state.activeGhostNodeId,
        };
      });
    },

    requestMoreDetail: (goalId: string) => {
      set((state) => {
        const newGoalHints = new Map(state.goalHints);
        const existing = newGoalHints.get(goalId);

        if (existing && existing.currentLevel !== 'full') {
          const nextLevel: HintLevel =
            existing.currentLevel === 'category' ? 'tactic' : 'full';

          newGoalHints.set(goalId, {
            ...existing,
            currentLevel: nextLevel,
            isLoading: true,
            error: null,
          });
        }

        return { goalHints: newGoalHints };
      });
    },

    setApiKey: (key: string | null) => {
      saveToStorage(STORAGE_KEY_API, key);
      set({ apiKey: key });
    },

    setLoraServerUrl: (url: string | null) => {
      saveToStorage(STORAGE_KEY_LORA, url);
      set({ loraServerUrl: url });
    },

    setLoraApiKey: (key: string | null) => {
      saveToStorage(STORAGE_KEY_LORA_API, key);
      set({ loraApiKey: key });
    },

    clearAllHints: () => {
      set({
        goalHints: new Map(),
        activeGhostNodeId: null,
      });
    },

    clearHint: (goalId: string) => {
      set((state) => {
        const newGoalHints = new Map(state.goalHints);
        newGoalHints.delete(goalId);

        return { goalHints: newGoalHints };
      });
    },

    getGoalHintState: (goalId: string) => {
      return get().goalHints.get(goalId);
    },
  }))
);

// Convenience selectors
export const useGoalHintState = (goalId: string) =>
  useHintStore((s) => s.goalHints.get(goalId));

export const useActiveGhostNode = () =>
  useHintStore((s) => {
    if (!s.activeGhostNodeId) return null;
    for (const hintState of s.goalHints.values()) {
      if (hintState.ghostNode?.id === s.activeGhostNodeId) {
        return hintState.ghostNode;
      }
    }
    return null;
  });

export const useHintApiKey = () => useHintStore((s) => s.apiKey);

/** The user's own General LLM key, or the build-time proxy; null when neither is set. */
export function useGeneralLlmAccess(): GeneralLlmAccess | null {
  const apiKey = useHintStore((s) => s.apiKey);
  const proxyUrl = useHintStore((s) => s.generalLlmProxyUrl);
  return useMemo(
    () => (hasGeneralLlm({ apiKey, proxyUrl }) ? { apiKey, proxyUrl } : null),
    [apiKey, proxyUrl],
  );
}
